    public ?string $_Detail {
        get => $this->getField(fieldName: "detail");
        set {
            $this->updateField(fieldName: "detail", value: $value);
        }
    }
    public ?string $_NotecardDetail {
        get => $this->getField(fieldName: "notecardDetail");
        set {
            $this->updateField(fieldName: "notecardDetail", value: $value);
        }
    }
    // Data Design
    protected $fields = [
        "id",
        "name",
        "detail",
        "notecardDetail",
    ];
    protected $dataset = [
        "id" => ["type" => "int", "value" => null],
        "name" => ["type" => "str", "value" => null],
        "detail" => ["type" => "str", "value" => null],
        "notecardDetail" => ["type" => "str", "value" => null],
    ];
    // Setters
    /**
    * setName
    */
    protected function setName(?string $newValue): void
    {
        $this->updateField("name", $newValue);
    }
    /**
    * setDetail
    */
    protected function setDetail(?string $newValue): void
    {
        $this->updateField("detail", $newValue);
    }
    /**
    * setNotecardDetail
    */
    protected function setNotecardDetail(?string $newValue): void
    {
        $this->updateField("notecardDetail", $newValue);
    }
    // Getters
    protected function getName(): ?string
    {
        return $this->getField("name");
    }
    protected function getDetail(): ?string
    {
        return $this->getField("detail");
    }
    protected function getNotecardDetail(): ?string
    {
        return $this->getField("notecardDetail");
    }
    // Loaders
    public function loadByName(string $name, ?array $limitFields = null): SingleLoadReply
    {
        return $this->loadByField(
            "name",
            $name
        , limitFields: $limitFields);
    }
    public function loadByDetail(string $detail, ?array $limitFields = null): SingleLoadReply
